public int lengthOfLongestSubstring(String s) {
    int[] lastSeen = new int[128];           // ASCII; stores index + 1, 0 means not seen
    int left = 0, best = 0;
    for (int right = 0; right < s.length(); right++) {
        char c = s.charAt(right);
        left = Math.max(left, lastSeen[c]);  // jump past the previous copy of c, never backwards
        lastSeen[c] = right + 1;
        best = Math.max(best, right - left + 1);
    }
    return best;
}

public int characterReplacement(String s, int k) {
    int[] counts = new int[26];
    int left = 0, maxFreq = 0, best = 0;
    for (int right = 0; right < s.length(); right++) {
        maxFreq = Math.max(maxFreq, ++counts[s.charAt(right) - 'A']);
        if ((right - left + 1) - maxFreq > k) {   // needs more than k changes
            counts[s.charAt(left) - 'A']--;
            left++;                                 // slide; window never shrinks below best
        }
        best = Math.max(best, right - left + 1);
    }
    return best;
}
